import React from "react";
import PropTypes from "prop-types";

import "../styles/ScreenSizeWarning.scss";

export default function ScreenSizeWarning({height, width}) {
  return (
    <div id="screen-warning">
      <div id="warning">Warning</div>
      <div id="warning-text">This app was designed for use with desktop displays. For a better user experience, please increase the {height ? "width" : (width ? "height" : "height and width")} of your browser window or view on a larger screen.</div>
      <div id="warning-close"></div>
    </div>
  );
}


ScreenSizeWarning.propTypes = {
  height: PropTypes.boolean.isRequired,
  width: PropTypes.boolean.isRequired
};
